function empty(text){return el('p','empty-state',text);}
function card(title){const n=el('section','card');if(title)n.append(el('h2','',title));return n;}
function title(text,caption,actions=[]){const h=el('div','view-heading');append(h,append(el('div'),el('span','eyebrow','CDE · INVENTÁRIO DIÁRIO'),el('h1','',text),caption?el('p','muted',caption):null),append(el('div','toolbar'),...actions));return h;}
function setMenu(open){document.body.classList.toggle('menu-open',open);$('nav-backdrop').hidden=!open;$('menu-toggle').textContent=open?'× Fechar':'☰ Menu';$('menu-toggle').setAttribute('aria-expanded',String(open));}
function renderNav(){const nav=$('sidebar-nav');nav.replaceChildren();navs.forEach(([key,icon,label])=>{const b=btn(icon+'  '+label,()=>navigate(key),'nav-button'+(currentPage===key?' active':''));b.setAttribute('aria-current',currentPage===key?'page':'false');nav.append(b);});}
function navigate(key){location.hash=key;setMenu(false);if(location.hash.slice(1)===key)render();}
function showError(host,e){host.replaceChildren(notice(e?.message||'Não foi possível concluir. Tente novamente.','error'));host.hidden=false;}
function readableError(e){const m=e?.message||String(e);if(/jwt|session|token.*expired/i.test(m))return 'Sua sessão expirou. Saia e entre novamente com o acesso do PDI.';return m;}
async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error)throw new Error(readableError(error));return data;}
function sender(){const ids=new Map();return async(action,payload)=>{const key=action+JSON.stringify(payload);if(!ids.has(key))ids.set(key,crypto.randomUUID());return rpc('invd_command',{p_action:action,p_request_id:ids.get(key),p_payload:payload});};}
async function refresh(){let out=[],offset=0;while(true){const page=await rpc('invd_list',{p_offset:offset,p_limit:500});const list=Array.isArray(page)?page:page?.rows||[];out.push(...list);if(list.length<500)break;offset+=500;if(offset>100000)throw new Error('Base muito extensa. Contate a gestão para revisar a consulta.');}rows=out;}
async function refreshRender(){await refresh();render();}
function field(form,label,name,type='text',value='',required=false){const box=el('div','field');const id='f-'+name+'-'+crypto.randomUUID().slice(0,6);const l=el('label','',label);l.htmlFor=id;let control;if(type==='select'){control=el('select');}else if(type==='textarea'){control=el('textarea');}else{control=el('input');control.type=type;}if(type==='textarea')control.maxLength=2000;if(type==='url')control.maxLength=2000;control.id=id;control.name=name;control.value=value??'';control.required=required;box.append(l,control);form.append(box);return control;}
function options(control,values,placeholder='Selecione…'){control.replaceChildren();if(placeholder!==null){const o=el('option','',placeholder);o.value='';control.append(o);}for(const value of values){const pair=Array.isArray(value)?value:[value,value];const o=el('option','',pair[1]);o.value=pair[0];control.append(o);}}
function catalogValues(category){const defaults={type:['Comum','Laminado','Espelho','Habitat','Outro'],color:['Verde','Incolor','Fumê','Cinza','Reflexivo','Âmbar'],thickness:['4','6','8','10','12'],warehouse:[]};const candidates=[...(defaults[category]||[]),...kinds('catalog').filter(r=>r.data.category===category).map(r=>r.data.value),...kinds('box').map(r=>({type:r.data.type,color:r.data.color,thickness:String(r.data.thickness_mm),warehouse:r.data.warehouse})[category])];const seen=new Set(),out=[];for(const candidate of candidates){let label=U.catalogText(candidate);if(category==='thickness'&&label&&Number.isFinite(Number(label.replace(',','.'))))label=String(Number(label.replace(',','.')));const key=U.catalogKey(label);if(label&&!seen.has(key)){seen.add(key);out.push(label);}}return out;}
function glassFields(form,{box=false}={}){const fields={};for(const [key,label,cat]of [['type','Tipo de vidro','type'],['color','Cor do vidro','color'],['thickness_mm','Espessura · mm','thickness'],['warehouse','Galpão / local','warehouse']]){const input=field(form,label,key,'select','',true);options(input,catalogValues(cat));fields[key]=input;}for(const[key,label]of [['width_mm','Largura da chapa · mm'],['height_mm','Altura da chapa · mm'],[box?'sheets':'quantity',box?'Chapas por caixa':'Quantidade de chapas avulsas'],['damaged','Chapas avariadas · incluídas no total']]){const input=field(form,label,key,'number',key==='damaged'?0:'',key!=='damaged');const dimension=key==='width_mm'||key==='height_mm';input.min=key==='damaged'?'0':dimension?'0.001':'1';input.step=dimension?'0.001':'1';input.max=dimension?'20000':'100000';fields[key]=input;}return fields;}
const values=fields=>Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,v.value]));
function openModal(name,build){closeModal();const overlay=el('div','modal-overlay');const dialog=el('section','app-modal');dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');const heading=el('h2','',name);heading.id='modal-title';dialog.setAttribute('aria-labelledby',heading.id);const close=btn('Fechar',closeModal,'small');const header=append(el('header','dialog-header'),heading,close);const body=el('div','dialog-body');append(dialog,header,body);overlay.append(dialog);$('modal-root').append(overlay);const previous=document.activeElement;const key=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);modalCleanup=()=>{document.removeEventListener('keydown',key);if(previous?.isConnected)previous.focus();};document.body.classList.add('modal-open');build(body,dialog);setTimeout(()=>dialog.querySelector('input,select,textarea,button')?.focus(),0);return body;}
function closeModal(){modalCleanup?.();modalCleanup=null;$('modal-root').replaceChildren();document.body.classList.remove('modal-open');}
function modalForm(name,build,action,after){const send=sender();openModal(name,body=>{const form=el('form','form-grid');const get=build(form);const errors=el('div','form-error');errors.hidden=true;errors.setAttribute('role','alert');const submit=el('button','button primary','Salvar');submit.type='submit';form.append(errors,append(el('div','form-actions'),btn('Cancelar',closeModal,'secondary'),submit));form.addEventListener('submit',async e=>{e.preventDefault();if(submit.disabled)return;submit.disabled=true;errors.hidden=true;try{const payload=get();const result=await send(action,payload);await refresh();closeModal();render();toast('Registro salvo.');after?.(result);}catch(error){showError(errors,error);}finally{submit.disabled=false;}});body.append(form);});}
function deleteRecord(kind,row){
 if(!context?.can_manage)return;
 const isInventory=kind==='inventory';const noun=isInventory?'inventário':'item';const send=sender();
 openModal('Excluir '+noun,body=>{
  const form=el('form','form-grid');
  form.append(notice(isInventory?'A exclusão remove a conferência do dia, suas leituras, contagens avulsas e validações. As caixas retornam à situação anterior à conferência. As entradas das caixas e os logs de auditoria são preservados. Só é possível excluir o inventário mais recente; havendo posteriores, exclua os mais recentes primeiro.':'A exclusão remove esta caixa do cadastro e do estoque. O histórico da operação será preservado. Se a caixa estiver vinculada a algum inventário, será necessário excluir as conferências correspondentes primeiro.','warning'));
  form.append(el('p','full-width',isInventory?'Inventário de '+dateText(row.work_date):row.data.code+' · '+boxName(row)));
  const reason=field(form,'Motivo da exclusão','reason','textarea','',true);reason.minLength=3;reason.maxLength=2000;
  const checkbox=el('input');checkbox.type='checkbox';checkbox.required=true;checkbox.name='confirm_delete';
  const consent=append(el('label','checkbox-label full-width'),checkbox,el('span','','Confirmo a exclusão deste '+noun+' e dos registros indicados acima.'));form.append(consent);
  const errors=el('div','form-error');errors.hidden=true;errors.setAttribute('role','alert');
  const submit=el('button','button danger small','× Excluir '+noun);submit.type='submit';
  form.append(errors,append(el('div','form-actions'),btn('Cancelar',closeModal,'secondary'),submit));
  form.addEventListener('submit',async e=>{e.preventDefault();if(submit.disabled)return;errors.hidden=true;const text=reason.value.trim();if(text.length<3||!checkbox.checked){showError(errors,new Error('Informe um motivo com pelo menos três caracteres e confirme a exclusão.'));return;}submit.disabled=true;
   try{await send(isInventory?'inventory_delete':'box_delete',{id:row.id,reason:text});await refresh();closeModal();navigate(isInventory?'history':'items');toast(isInventory?'Inventário excluído. O estado anterior das caixas foi restaurado.':'Item excluído.');}
   catch(error){showError(errors,error);}finally{submit.disabled=false;}
  });body.append(form);
 });
}
function table(headers,bodyRows){const wrap=el('div','table-scroll');const t=el('table');const head=el('thead');const tr=el('tr');headers.forEach(h=>tr.append(el('th','',h)));head.append(tr);const body=el('tbody');bodyRows.forEach(cells=>{const row=el('tr');cells.forEach(value=>{const cell=el('td');if(value instanceof Node)cell.append(value);else cell.textContent=value??'—';row.append(cell);});body.append(row);});append(t,head,body);wrap.append(t);return wrap;}
function stat(label,value,detail){return append(el('article','stat-card'),el('span','stat-label',label),el('strong','stat-value',value),el('small','muted',detail||''));}
function statsSummary(boxes,loose=[]){const s=U.summarize(boxes,loose);return {sheets:s.sheets_box,m2:s.m2_box,damaged:s.sheets_damaged,looseSheets:s.sheets_loose,looseM2:s.m2_loose,good:s.sheets_good,goodM2:s.m2_good};}
function overview(main){
 const current=active(),analytics=buildAnalytics(rows,dashboardFilters),k=analytics.kpis,meta=analytics.meta;const hasReorderRules=analytics.replenishment.some(r=>r.enabled);
 const completed=kinds('inventory').filter(r=>r.data.status==='closed').sort((a,b)=>b.work_date.localeCompare(a.work_date)||b.created_at.localeCompare(a.created_at))[0];
 const matches=row=>{const d=row.data;return ['warehouse','type','color'].every(key=>!dashboardFilters[key]||U.catalogKey(d[key])===U.catalogKey(dashboardFilters[key]))&&(!dashboardFilters.thickness_mm||Number(d.thickness_mm)===Number(dashboardFilters.thickness_mm));};
 const boxes=kinds('box').filter(r=>r.data.status==='sealed'&&matches(r)),loose=completed?kinds('loose').filter(r=>r.parent_id===completed.id&&matches(r)):[];
 main.append(title('Visão geral','Estoque útil e acompanhamento das conferências.',[btn('Atualizar dados',async()=>{try{await refreshRender();toast('Dados atualizados.');}catch(e){toast(e.message,true);}},'secondary')]));
 const filters=card('Filtros do estoque');const form=el('form','overview-filters form-grid'),controls={};
 for(const[name,label,category]of [['warehouse','Galpão','warehouse'],['type','Tipo de vidro','type'],['color','Cor de vidro','color'],['thickness_mm','Espessura · mm','thickness']]){const input=field(form,label,name,'select');options(input,catalogValues(category),'Todos');input.value=U.catalogText(dashboardFilters[name]);controls[name]=input;}
 const from=field(form,'Conferências · de','from','date',dashboardFilters.from),to=field(form,'Conferências · até','to','date',dashboardFilters.to);from.max=nowDate();to.max=nowDate();controls.from=from;controls.to=to;
 const error=el('div','form-error');error.hidden=true;error.setAttribute('role','alert');const apply=el('button','button','Aplicar filtros');apply.type='submit';form.append(error,append(el('div','form-actions'),apply,btn('Limpar filtros',()=>{dashboardFilters={warehouse:'',type:'',color:'',thickness_mm:'',from:'',to:''};render();},'secondary')));
 form.addEventListener('submit',e=>{e.preventDefault();const next=values(controls);if(next.from&&next.to&&next.from>next.to){showError(error,new Error('A data inicial deve ser anterior ou igual à data final.'));return;}dashboardFilters=next;render();});filters.append(form,el('p','muted','As datas filtram a evolução das conferências. Os indicadores de estoque mostram a posição atual.'));main.append(filters);
 const grid=el('div','stats-grid overview-stats');append(grid,stat('Chapas úteis',num(k.useful_sheets,0),num(k.useful_m2)+' m² sem avarias'),stat('Área útil em caixa',num(k.sealed_useful_m2)+' m²',num(boxes.length,0)+' caixa(s) no recorte'),stat('Área útil avulsa',num(k.loose_useful_m2)+' m²',num(loose.reduce((n,r)=>n+Number(r.data.quantity)-Number(r.data.damaged||0),0),0)+' chapas úteis avulsas'),stat('Chapas avariadas',num(k.damaged_percent)+'%',num(k.damaged_sheets,0)+' de '+num(k.physical_sheets,0)+' chapas físicas'),stat('Reposição sugerida',hasReorderRules?num(k.replenishment_sheets,0)+' chapas':'Não configurada',hasReorderRules?num(k.replenishment_m2)+' m² · '+num(k.replenishment_count,0)+' vidro(s) · todos os galpões':context.can_manage?'Defina mínimo e alvo em Cadastros':'Mínimo e alvo aguardando definição pela gestão'));main.append(grid);
 const missing=kinds('box').filter(r=>r.data.status==='missing');if(missing.length)main.append(notice(`${missing.length} caixa(s) não localizada(s). Essas quantidades não entram no estoque físico confirmado.`,'warning'));
 if(meta.provisional)main.append(notice(meta.has_active?'Conferência em andamento: os indicadores e a reposição sugerida são provisórios.':'Ainda não há conferência concluída. As chapas avulsas não foram validadas; a reposição sugerida é provisória.','warning'));
 const session=card('Conferência diária');session.append(completed?el('p','',`Último inventário concluído: ${dateText(completed.work_date)}.`):empty('Ainda não há inventário concluído.'));session.append(btn(current?'Continuar conferência':'Iniciar inventário diário',()=>current?navigate('daily'):startInventory()));main.append(session);
 const charts=el('div','chart-grid');for(const[kind,label,data]of [['type','Área útil por tipo de vidro',analytics.charts.by_type],['warehouse','Estoque útil por galpão',analytics.charts.by_warehouse],['condition','Chapas úteis e avariadas',analytics.charts.condition],['evolution','Evolução do estoque útil',analytics.charts.evolution]]){const detail=el('details','card chart-panel');detail.dataset.chart=kind;detail.open=chartOpen[kind];detail.append(el('summary','',label));const body=el('div','chart-body');body.append(renderInventoryChart(kind,data));detail.append(body);detail.addEventListener('toggle',()=>{chartOpen[kind]=detail.open;});charts.append(detail);}main.append(charts);
 const reorder=card('Reposição · todos os galpões');reorder.classList.add('reorder-panel','replenishment-table');reorder.append(el('p','muted','Os parâmetros consideram a soma de todos os galpões. O filtro de galpão não altera esta sugestão.'));const rules=analytics.replenishment.filter(r=>r.enabled);reorder.append(rules.length?table(['Vidro','Chapas úteis','Mínimo','Alvo','Reposição · chapas','Reposição · m²','Situação'],rules.map(r=>[boxName(r.spec),num(r.useful_sheets,0),num(r.minimum_sheets,0),num(r.target_sheets,0),num(r.needed_sheets,0),num(r.needed_m2),el('span','badge '+(r.triggered?'warning':'success'),r.triggered?'Repor':'Sem reposição necessária')])):empty('Nenhum parâmetro de reposição ativo para este recorte.'));if(context.can_manage)reorder.append(btn('Configurar reposição',()=>navigate('catalog'),'small secondary'));main.append(reorder);
 const detail=el('details','card stock-detail');detail.append(el('summary','','Detalhamento do estoque atual'));detail.append(groupTable(boxes,loose),el('p','muted','As quantidades físicas incluem as chapas avariadas. A área útil dos indicadores desconta as avarias.'));main.append(detail);
}
function groupTable(boxes,loose=[]){const groups=new Map();function add(row,isLoose){const d=row.data||row;const key=U.sku(d);if(!groups.has(key))groups.set(key,{d,boxes:0,sheets:0,loose:0,m2Box:0,m2Loose:0,damaged:0});const g=groups.get(key),quantity=Number(isLoose?d.quantity:d.sheets);g[isLoose?'loose':'sheets']+=quantity;if(!isLoose)g.boxes++;g[isLoose?'m2Loose':'m2Box']+=U.area(d,quantity);g.damaged+=Number(d.damaged||0);}boxes.forEach(b=>add(b,false));loose.forEach(b=>add(b,true));if(!groups.size)return empty('Nenhum item neste recorte.');return table(['Tipo / cor / espessura / dimensões','Caixas','Chapas em caixa','Avulsas','m² em caixa','m² avulsos','Avarias'],[...groups.values()].map(g=>[boxName(g.d),num(g.boxes,0),num(g.sheets,0),num(g.loose,0),num(g.m2Box),num(g.m2Loose),num(g.damaged,0)]));}
function entryForm(){if(active()){toast('Encerre o inventário em andamento antes de registrar novas entradas.',true);return;}if(!catalogValues('warehouse').length){toast('Cadastre primeiro um galpão na aba Cadastros.',true);navigate('catalog');return;}modalForm('Receber caixa de vidro',form=>{const invoice=field(form,'Número da nota fiscal','invoice','text','',true);invoice.maxLength=80;const f=glassFields(form,{box:true});const photo=field(form,'Link da foto · opcional','photo_url','url');const notes=field(form,'Observações da entrada','notes','textarea');return ()=>({items:[{...U.validateBox({...values(f),invoice:invoice.value.trim(),photo_url:photo.value.trim()}),notes:notes.value.trim()}]});},'box_create',result=>{if(result?.id)location.hash='item='+result.id;});}
function entries(main){main.append(title('Entradas','Receba uma caixa por registro ou importe várias linhas de uma planilha.',[btn('Nova entrada',entryForm)]));if(active())main.append(notice('Há uma conferência em andamento. Finalize-a antes de adicionar novas caixas.','warning'));const importCard=card('Importar XLSX');importCard.append(el('p','muted','Uma linha identifica uma caixa. As entradas são acrescentadas ao estoque; revise a prévia antes de confirmar.'));const controls=el('div','toolbar');const template=btn('Baixar modelo XLSX',downloadTemplate,'export');const pick=el('input');pick.type='file';pick.accept='.xlsx';pick.id='import-file';const label=el('label','','Selecionar arquivo XLSX');label.htmlFor=pick.id;controls.append(template);importCard.append(controls,label,pick);pick.disabled=Boolean(active());pick.addEventListener('change',()=>importFile(pick.files?.[0],importCard));main.append(importCard);const recent=card('Últimas entradas');const list=kinds('box').slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,30);recent.append(list.length?table(['Identificação','Vidro','Nota fiscal','Galpão','Chapas','Registro'],list.map(b=>[itemLink(b),boxName(b),b.data.invoice,b.data.warehouse,num(b.data.sheets,0),dateText(b.created_at)])):empty('Nenhuma caixa recebida.'));main.append(recent);}
function downloadTemplate(){try{const headers=U.templateHeaders;const sheet=XLSX.utils.aoa_to_sheet([headers]);sheet['!cols']=headers.map(()=>({wch:23}));const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'Entradas');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Orientações'],['Uma linha = uma caixa. Dimensões e espessura em milímetros.'],['Avarias fazem parte do total de chapas. Não subtrair do total informado.'],['Use os tipos, cores e galpões cadastrados no sistema.'],['Não inclua fórmulas. Limite: 500 caixas por arquivo.']]),'Leia-me');XLSX.writeFile(book,'modelo-entradas-cde.xlsx');}catch(e){toast('Não foi possível gerar o modelo: '+e.message,true);}}
async function importFile(file,host){host.querySelector('.import-preview')?.remove();if(!file)return;const preview=el('div','import-preview');host.append(preview);try{if(!/\.xlsx$/i.test(file.name))throw new Error('Selecione um arquivo .xlsx.');if(file.size>10*1024*1024)throw new Error('O arquivo deve ter até 10 MB.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,cellFormula:true});const sheet=wb.Sheets[wb.SheetNames[0]];if(!sheet)throw new Error('A planilha está vazia.');if(Object.values(sheet).some(c=>c&&typeof c==='object'&&c.f))throw new Error('A planilha contém fórmulas. Cole somente valores antes de importar.');const raw=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:true});const parsed=U.parseImport(raw);if(parsed.errors?.length){preview.append(notice('Corrija as linhas abaixo antes de importar. Nenhuma entrada foi salva.','error'));const list=el('ul');parsed.errors.slice(0,50).forEach(e=>list.append(el('li','',typeof e==='string'?e:`Linha ${e.row||e.line||'—'}: ${e.message||e.error||JSON.stringify(e)}`)));preview.append(list);return;}const items=parsed.items;if(!items?.length)throw new Error('Nenhuma caixa válida foi encontrada.');if(items.length>500)throw new Error('Importe no máximo 500 caixas por arquivo.');preview.append(el('h3','',`${items.length} caixa(s) para conferir`));preview.append(table(['Linha','Nota fiscal','Vidro','Galpão','Chapas','Avarias'],items.slice(0,50).map((b,i)=>[i+2,b.invoice,boxName(b),b.warehouse,num(b.sheets,0),num(b.damaged,0)])));if(items.length>50)preview.append(el('p','muted','Prévia das primeiras 50 caixas; a confirmação inclui todas as linhas válidas.'));const send=sender();const confirm=btn('Confirmar '+items.length+' entrada(s)',async()=>{confirm.disabled=true;try{await send('box_create',{items});await refreshRender();toast('Importação concluída. As etiquetas estão disponíveis na página de cada item.');}catch(e){preview.append(notice(e.message,'error'));confirm.disabled=false;}});preview.append(confirm);}catch(e){preview.append(notice(e.message,'error'));}}
function itemLink(b){const link=el('a','item-link',b.data.code||b.id);link.href='#item='+b.id;return link;}
