 const win=window.open('','_blank');if(!win){toast('Permita a abertura de janelas para imprimir a etiqueta.',true);return;}
 win.document.title='Etiqueta '+b.data.code;win.document.documentElement.lang='pt-BR';win.document.documentElement.dataset.theme='light';win.document.body.className='label-print';
