function catalog(main){main.append(title('Cadastros','Mantenha os seletores usados nas entradas e na contagem diária.'));const c=card('Adicionar opção');const form=el('form','form-grid');const category=field(form,'Cadastro','category','select','',true);options(category,[['type','Tipo de vidro'],['color','Cor de vidro'],['thickness','Espessura · mm'],['warehouse','Galpão / local']]);const value=field(form,'Nome / valor','value','text','',true);value.maxLength=80;const error=el('div','form-error');error.hidden=true;const save=el('button','button','Adicionar');save.type='submit';form.append(error,append(el('div','form-actions'),save));let send=sender();form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{await send('catalog_add',{category:category.value,value:U.catalogText(value.value)});await refreshRender();toast('Opção cadastrada.');send=sender();}catch(ex){showError(error,ex);}finally{save.disabled=false;}});c.append(form);main.append(c);const grid=el('div','group-grid');for(const [key,label]of [['warehouse','Galpões / locais'],['type','Tipos de vidro'],['color','Cores'],['thickness','Espessuras · mm']]){const c=card(label);const list=el('ul','catalog-list');catalogValues(key).forEach(v=>list.append(el('li','',v)));c.append(list.childNodes.length?list:empty('Cadastre o primeiro galpão para iniciar.'));grid.append(c);}main.append(grid);reorderCatalog(main);}
