  for(const[key,label,category]of [['type','Tipo de vidro','type'],['color','Cor de vidro','color'],['thickness_mm','Espessura · mm','thickness']]){const input=field(form,label,key,'select','',true);options(input,catalogValues(category));input.value=U.catalogText(d[key]??'');fields[key]=input;}
