function startInventory(){if(active()){navigate('daily');return;}modalForm('Iniciar inventário diário',form=>{const date=field(form,'Dia da conferência','date','date',nowDate(),true);date.max=nowDate();form.append(notice('Todas as caixas fechadas entram nesta conferência, em todos os galpões. Escaneie na ordem em que encontrar as caixas. Novas entradas ficam pausadas até o encerramento.'));return()=>({date:date.value});},'inventory_start',()=>navigate('daily'));}
function normalizeCode(raw){const text=String(raw).trim();try{const url=new URL(text);const item=new URLSearchParams(url.hash.replace(/^#/,''));if(item.has('item'))return item.get('item');}catch{}return text.replace(/^#?item=/,'');}
