function removeLoose(row){const send=sender();openModal('Remover contagem avulsa',body=>{body.append(el('p','','Remover este lançamento da conferência atual? A alteração ficará no histórico.'));const error=el('div');const remove=btn('× Remover',async()=>{remove.disabled=true;try{await send('inventory_loose_remove',{id:row.id});await refresh();closeModal();render();toast('Contagem removida.');}catch(e){showError(error,e);remove.disabled=false;}},'danger');body.append(error,append(el('div','form-actions'),btn('Cancelar',closeModal,'secondary'),remove));});}
function decisionForm(inv,box,existing){modalForm('Validar caixa '+box.data.code,form=>{form.append(el('p','full-width',boxName(box)),el('p','muted full-width',`${num(box.data.sheets,0)} chapas · ${box.data.warehouse} · NF ${box.data.invoice}`));const outcome=field(form,'Situação encontrada','outcome','select','',true);options(outcome,[['opened','Confirmo que foi aberta'],['sealed','Continua fechada · conferência manual'],['missing','Não localizada · registrar ocorrência']]);outcome.value=existing?.data.outcome||'';const notes=field(form,'Observação / ocorrência','notes','textarea',existing?.data.notes||'');outcome.addEventListener('change',()=>{notes.required=outcome.value!=='opened';});notes.required=existing?.data.outcome&&existing.data.outcome!=='opened';form.append(notice('Chapas avulsas ficam agrupadas por tipo, cor, espessura e dimensões. Havendo mais de uma caixa compatível, a nota fiscal de origem não é presumida.'));return()=>({inventory_id:inv.id,box_id:box.id,outcome:outcome.value,notes:notes.value.trim()});},'inventory_decide');}
function reconciliation(inv){const boxes=(inv.data.expected||[]).map(id=>kinds('box').find(r=>r.id===id)).filter(Boolean);const scans=kinds('scan').filter(r=>r.parent_id===inv.id);const loose=kinds('loose').filter(r=>r.parent_id===inv.id);const decisions=kinds('decision').filter(r=>r.parent_id===inv.id);const opened=boxes.filter(b=>decisions.some(d=>d.data.box_id===b.id&&d.data.outcome==='opened'));const groups=new Map();for(const b of [...opened,...loose]){const d=b.data,key=U.sku(d);if(!groups.has(key))groups.set(key,{data:d,boxes:[],loose:0,damaged:0});const g=groups.get(key);if(b.kind==='box')g.boxes.push(b);else{g.loose+=Number(d.quantity);g.damaged+=Number(d.damaged||0);}}const wrap=el('div');if(!groups.size){wrap.append(empty('Confirme as aberturas e registre as chapas avulsas para comparar.'));return wrap;}wrap.append(table(['Vidro','Caixas abertas nesta conferência','Chapas nas caixas abertas','Avulsas contadas','Diferença versus capacidade aberta hoje','Origem'],[...groups.values()].map(g=>{const expected=g.boxes.reduce((s,b)=>s+Number(b.data.sheets),0);return[boxName(g.data),num(g.boxes.length,0),num(expected,0),num(g.loose,0),num(g.loose-expected,0),'Origem não determinada · pode incluir saldos anteriores'];})));wrap.append(notice('O comparativo mostra as caixas abertas nesta conferência e as avulsas contadas hoje. Avulsas podem incluir saldos de dias anteriores; divergência não significa consumo ou quebra automaticamente. A origem por nota fiscal não é atribuída quando houver mais de uma caixa compatível.'));return wrap;}
function scanCamera(inv){openModal('Escanear QR Code ou código de barras',body=>{const video=el('video','scan-video');video.autoplay=true;video.muted=true;video.setAttribute('playsinline','');const feedback=el('div');feedback.setAttribute('role','status');body.append(el('p','muted','Aponte a câmera para a etiqueta. A leitura confirma a caixa neste inventário.'),video,feedback);let controls,stopped=false,busy=false,last='';const previous=modalCleanup;modalCleanup=()=>{stopped=true;controls?.stop();video.srcObject?.getTracks?.().forEach(t=>t.stop());previous?.();};const send=sender();if(!window.ZXingBrowser?.BrowserMultiFormatReader){feedback.append(notice('Leitor de câmera indisponível. Feche e use o campo de código ou um leitor físico.','warning'));return;}const reader=new ZXingBrowser.BrowserMultiFormatReader();reader.decodeFromVideoDevice(undefined,video,async(result,error,control)=>{controls=control;if(stopped){controls?.stop();return;}if(!result||busy)return;const code=normalizeCode(result.getText());if(code===last)return;last=code;busy=true;try{await send('inventory_scan',{inventory_id:inv.id,code});await refresh();feedback.replaceChildren(notice('Caixa conferida: '+code,'success'));navigator.vibrate?.(70);render();}catch(e){feedback.replaceChildren(notice(e.message,'error'),btn('Tentar leitura novamente',()=>{last='';feedback.replaceChildren(notice('Aponte novamente para a etiqueta.'));},'small'));}finally{busy=false;}}).then(c=>{controls=c;if(stopped)c.stop();}).catch(e=>{if(!stopped)feedback.replaceChildren(notice('Não foi possível abrir a câmera. Confira a permissão do navegador e use uma conexão HTTPS. Você também pode digitar o código ou usar um leitor físico.','warning'));});});}
function history(main){main.append(title('Histórico','Consulte conferências concluídas e os registros de cada operação.'));const invs=kinds('inventory').slice().sort((a,b)=>b.work_date.localeCompare(a.work_date)||b.created_at.localeCompare(a.created_at));const c=card('Inventários');c.append(invs.length?table(['Data','Situação','Caixas esperadas','Registro'],invs.map(r=>{const a=el('a','text-link','Ver conferência');a.href='#inventory='+r.id;const actions=append(el('div','toolbar'),a);if(context.can_manage)actions.append(btn('× Excluir inventário',()=>deleteRecord('inventory',r),'danger small'));return[dateText(r.work_date),statusBadge(r.data.status),num(r.data.expected?.length||0,0),actions];})):empty('Nenhum inventário registrado.'));main.append(c);if(!context.can_manage)return;const logs=card('Log de operações');const entries=kinds('log').sort((a,b)=>b.created_at.localeCompare(a.created_at));logs.append(entries.length?table(['Quando','Responsável','Ação','Referência'],entries.slice(0,250).map(r=>[new Date(r.created_at).toLocaleString('pt-BR'),r.created_by_name||r.data.actor_name||r.created_by,r.data.action||r.data.event||'Operação',r.data.entity_id||r.data.result?.id||r.parent_id||'—'])):empty('Nenhuma operação registrada.'));if(entries.length>250)logs.append(el('p','muted','Exibindo as 250 operações mais recentes.'));main.append(logs);}
function inventoryPage(main,id){const inv=kinds('inventory').find(r=>r.id===id);if(!inv){main.append(title('Conferência'),notice('Inventário não encontrado.','error'));return;}if(inv.data.status==='active'){navigate('daily');return;}main.append(title('Conferência de '+dateText(inv.work_date),'Registro concluído e preservado para consulta.',[btn('Voltar ao histórico',()=>navigate('history'),'secondary')]));const scans=kinds('scan').filter(r=>r.parent_id===id),loose=kinds('loose').filter(r=>r.parent_id===id),decisions=kinds('decision').filter(r=>r.parent_id===id);const sealed=(inv.data.expected||[]).map(bid=>kinds('box').find(r=>r.id===bid)).filter(Boolean).filter(b=>scans.some(s=>s.data.box_id===b.id)||decisions.some(d=>d.data.box_id===b.id&&d.data.outcome==='sealed'));const c=card('Quantidades conferidas');c.append(groupTable(sealed,loose));main.append(c);const rec=card('Reconciliação registrada');rec.append(reconciliation(inv));main.append(rec);const occurrences=decisions.filter(d=>d.data.notes||d.data.outcome==='missing');if(occurrences.length){const c=card('Observações e ocorrências');c.append(table(['Caixa','Situação','Relato'],occurrences.map(d=>{const b=kinds('box').find(b=>b.id===d.data.box_id);return[b?itemLink(b):d.data.box_id,statusLabel(d.data.outcome),d.data.notes||'—'];})));main.append(c);}const exportRows=[['Código','Tipo','Cor','Espessura mm','Largura mm','Altura mm','Galpão','Situação','Chapas','Avarias'],...sealed.map(b=>[b.data.code,b.data.type,b.data.color,b.data.thickness_mm,b.data.width_mm,b.data.height_mm,b.data.warehouse,'Caixa fechada',b.data.sheets,b.data.damaged]),...loose.map(b=>['Avulso',b.data.type,b.data.color,b.data.thickness_mm,b.data.width_mm,b.data.height_mm,b.data.warehouse,'Avulsas',b.data.quantity,b.data.damaged])];main.append(btn('Exportar conferência CSV',()=>downloadCSV(exportRows,'inventario-'+inv.work_date+'.csv'),'export'));if(context.can_manage)main.append(btn('× Excluir inventário',()=>deleteRecord('inventory',inv),'danger small'));}
function downloadCSV(data,filename){const text='\ufeff'+data.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'}));const a=el('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){labelObserver?.disconnect();if(!context)return;let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'overview');}catch{hash='overview';}currentPage=hash.startsWith('item=')?'items':hash.startsWith('inventory=')?'history':navs.some(n=>n[0]===hash)?hash:'overview';renderNav();$('breadcrumb-page').textContent=navs.find(n=>n[0]===currentPage)?.[2]||'Inventário';const main=$('main-content');main.replaceChildren();try{if(hash.startsWith('item='))itemPage(main,hash.slice(5));else if(hash.startsWith('inventory='))inventoryPage(main,hash.slice(10));else({overview,entries,daily,items,catalog,history}[currentPage])(main);}catch(e){main.append(notice('Não foi possível montar esta tela: '+e.message,'error'));}}
async function enter(){if(loading)return;loading=true;try{const {data:{user},error}=await db.auth.getUser();if(error||!user){$('login-screen').hidden=false;$('app-screen').hidden=true;return;}context=await rpc('invd_context',{});if(!context?.allowed){context=null;$('login-screen').hidden=false;$('app-screen').hidden=true;$('login-error').textContent='Seu perfil do PDI ainda não possui autorização para este inventário. Solicite o acesso à gestão.';$('login-error').hidden=false;return;}await refresh();$('viewer-name').textContent=context.profile.full_name;$('viewer-meta').textContent=[context.profile.sector,context.profile.position].filter(Boolean).join(' · ');$('viewer-avatar').textContent=context.profile.full_name.split(/\s+/).map(x=>x[0]).slice(0,2).join('');$('login-screen').hidden=true;$('app-screen').hidden=false;$('today-label').textContent=new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});render();}catch(e){$('login-screen').hidden=false;$('app-screen').hidden=true;$('login-error').textContent=readableError(e);$('login-error').hidden=false;}finally{loading=false;}}
async function boot(){try{const config=window.INV_CONFIG;if(!config?.url||!config?.key||!window.supabase?.createClient)throw new Error('Configuração de acesso indisponível. Atualize a página ou contate a gestão.');db=supabase.createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false,storageKey:'cde-inventory-auth'}});if(config.pdiUrl){$('return-pdi').href=config.pdiUrl;$('login-pdi').href=config.pdiUrl;}$('login-form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('button[type=submit]');submit.disabled=true;$('login-error').hidden=true;try{const{error}=await db.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error)throw new Error(/invalid login/i.test(error.message)?'E-mail ou senha inválidos. Use o mesmo acesso do PDI.':readableError(error));$('password').value='';await enter();}catch(error){$('login-error').textContent=error.message;$('login-error').hidden=false;}finally{submit.disabled=false;}});$('logout-button').addEventListener('click',async()=>{try{await db.auth.signOut({scope:'local'});context=null;rows=[];labelObserver?.disconnect();closeModal();setMenu(false);$('app-screen').hidden=true;$('login-screen').hidden=false;$('password').value='';}catch(e){toast(e.message,true);}});$('theme-button').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('cde-inventory-theme',theme);}catch{}});$('menu-toggle').addEventListener('click',()=>setMenu(!document.body.classList.contains('menu-open')));$('nav-backdrop').addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});window.addEventListener('hashchange',render);db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){context=null;rows=[];labelObserver?.disconnect();closeModal();setMenu(false);$('app-screen').hidden=true;$('login-screen').hidden=false;}});await enter();}catch(e){$('login-error').textContent=e.message;$('login-error').hidden=false;}}
boot();
